function loadSave() {
  try {
    if (!globalThis?.localStorage) return null;
    const current = globalThis.localStorage.getItem(SAVE_KEY);
    if (current) return JSON.parse(current);
    const legacy = globalThis.localStorage.getItem(LEGACY_KEY);
    return legacy ? JSON.parse(legacy) : null;
  } catch { return null; }
}
function saveGame(data) {
  try { if (globalThis?.localStorage) globalThis.localStorage.setItem(SAVE_KEY, JSON.stringify(data)); } catch {}
}
function routeById(id) { return ROUTES.find(r=>r.id===id)||ROUTES[0]; }
function makeService(platform, routeId, sets=1) { return { platform,routeId,sets,phase:'arriving',countdown:2,delay:0,hold:0,onboard:0 }; }
function parkingCapacity(lv){ const n=Math.max(1,lv); return 110+(n-1)*70+Math.floor((n-1)/3)*35; }
function entranceCapacity(lv){ return 55+(Math.max(1,lv)-1)*35; }
function ticketCapacity(lv){ return 48+(Math.max(1,lv)-1)*30; }
function securityCapacity(lv){ return 44+(Math.max(1,lv)-1)*28; }
function waitingCapacity(lv,stationLevel){ return 110+(Math.max(1,lv)-1)*60+(stationLevel-1)*20; }
function platformCapacity(lv,platforms){ return (100+(Math.max(1,lv)-1)*55)*platforms; }
function trainCapacity(service,levels,stationLevel){ return (120+Math.max(1,levels.train)*70+(stationLevel-1)*20)*service.sets; }
function milestone(kind,level){ return MILESTONES[kind]?.[level]||null; }
function nextMilestone(kind,level){ const keys=Object.keys(MILESTONES[kind]||{}).map(Number).filter(x=>x>level).sort((a,b)=>a-b); return keys[0]?{level:keys[0],name:MILESTONES[kind][keys[0]]}:null; }
function effectFor(kind,nextLevel){
  if(kind==='parking') return `+${parkingCapacity(nextLevel)-parkingCapacity(Math.max(1,nextLevel-1))} spaces`;
  if(kind==='entrance') return '+3 entry pax/s';
  if(kind==='ticket') return '+3 ticket pax/s';
  if(kind==='security') return '+3 security pax/s';
  if(kind==='waiting') return '+60 hall capacity';
  if(kind==='platform') return '+55 platform capacity';
  if(kind==='train') return '+70 seats / set';
  if(kind==='signage') return '+2 routing pax/s';
  if(kind==='cafe') return '+€3 / sec';
  if(kind==='shop') return '+€4 / sec';
  if(kind==='cleaning') return '+ satisfaction recovery';
  if(kind==='toilet') return '+ comfort recovery';
  if(kind==='restaurant') return '+€7 / sec';
  if(kind==='vip') return '+ departure bonus';
  if(kind==='manager') return '+ faster automation';
  return '+ capacity';
}

