  const effectiveLevel=devLevel??stationLevel,stage=STAGES[effectiveLevel-1],unlockedRoutes=ROUTES.filter(r=>r.unlock<=effectiveLevel),platformsUnlocked=effectiveLevel>=8?3:effectiveLevel>=4?2:1,maxSets=effectiveLevel>=7?3:effectiveLevel>=4?2:1,rush=(clock%90)>=70;
