  const departService=(platform)=>{const current=servicesRef.current.find(s=>s.platform===platform);if(!current||current.phase!=='ready')return;const route=routeById(current.routeId),routeDemand={...demandRef.current},stranded=routeDemand[route.id]||0,quality=.85+satRef.current/100*.25,trainBonus=1+(Math.max(1,levelsRef.current.train)-1)*.06+(levelsRef.current.vip||0)*.015,gross=Math.round(current.onboard*route.fare*quality*trainBonus),operating=30*current.sets,bonus=current.delay<=3?160:current.delay<=8?70:0,payout=Math.max(0,gross-operating+bonus);addCash(payout);servedRef.current+=current.onboard;departuresRef.current+=1;setServed(servedRef.current);setDepartures(departuresRef.current);changeSat(-(Math.min(7,stranded*.025)+Math.max(0,current.delay-4)*.12)+(current.delay<=3?1:0));const next=servicesRef.current.map(s=>s.platform===platform?{...s,phase:'departing',countdown:2,delay:0,hold:0}:s);servicesRef.current=next;setServices(next);setMessage(`${route.name} departed with ${current.onboard}. Revenue ${money(payout)}.`);setFlash(`+${money(payout)}`);setTimeout(()=>setFlash(''),1100);};

