    const managerLv=lv.manager||0;if(managerLv>0){const threshold=Math.max(1,5-Math.floor(managerLv/3)),auto=nextServices.find(x=>x.phase==='ready'&&x.delay>=threshold);if(auto){servicesRef.current=nextServices;demandRef.current=routeDemand;setServices(nextServices);setDemand(routeDemand);setTimeout(()=>departService(auto.platform),20);}}
    const passive=(lv.cafe||0)*3+(lv.shop||0)*4+(lv.restaurant||0)*7+(lv.vip||0)*5;if(passive>0)addCash(passive);const ratios=[pk/parkingCap,en/entranceCap,tk/ticketCap,se/securityCap,wa/waitingCap,Object.values(routeDemand).reduce((a,b)=>a+b,0)/platformCap],worst=Math.max(...ratios),recovery=(lv.cleaning||0)*.012+(lv.toilet||0)*.007+(lv.signage||0)*.003;if(worst<.7)changeSat(.035+recovery);else if(worst>.98)changeSat(-.12+Math.min(.08,recovery));else if(recovery>0)changeSat(Math.min(.035,recovery));
